IERC20Token targetToken = _path[i];

if (etherTokens[sourceToken])
sourceToken = IERC20Token(ETH_RESERVE_ADDRESS);
if (etherTokens[targetToken])
targetToken = IERC20Token(ETH_RESERVE_ADDRESS);

